import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static long[] prefix(long[] v, int size) {
        long[] a = Arrays.copyOf(v, size);
        Arrays.sort(a);
        long[] p = new long[size + 1];
        for (int i = 0; i < size; i++) p[i + 1] = p[i] + a[i];
        return p;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] both = new long[n], one = new long[n], two = new long[n];
        int nb = 0, nx = 0, ny = 0;
        for (int i = 0; i < n; i++) {
            long c = nextLong();
            long x = nextLong(), y = nextLong();
            if (x != 0 && y != 0) both[nb++] = c;
            else if (x != 0) one[nx++] = c;
            else if (y != 0) two[ny++] = c;
        }
        long[] B = prefix(both, nb), X = prefix(one, nx), Y = prefix(two, ny);
        StringBuilder out = new StringBuilder();
        for (int k = 1; k <= n; k++) {
            if (k > 1) out.append(' ');
            int lo = Math.max(0, Math.max(k - nx, k - ny)), hi = Math.min(k, nb);
            if (lo > hi) {
                out.append(-1);
                continue;
            }
            // cost(j) = B[j] + X[k-j] + Y[k-j] is convex in j: find the first non-negative difference.
            int l = lo, r = hi;
            while (l < r) {
                int m = (l + r) / 2;
                long diff = (B[m + 1] + X[k - m - 1] + Y[k - m - 1]) - (B[m] + X[k - m] + Y[k - m]);
                if (diff >= 0) r = m;
                else l = m + 1;
            }
            out.append(B[l] + X[k - l] + Y[k - l]);
        }
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func prefix(v []int64) []int64 {
	slices.Sort(v)
	p := make([]int64, len(v)+1)
	for i, x := range v {
		p[i+1] = p[i] + x
	}
	return p
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	var both, one, two []int64
	for i := 0; i < n; i++ {
		c, x, y := nextInt(), nextInt(), nextInt()
		if x != 0 && y != 0 {
			both = append(both, c)
		} else if x != 0 {
			one = append(one, c)
		} else if y != 0 {
			two = append(two, c)
		}
	}
	B, X, Y := prefix(both), prefix(one), prefix(two)
	nb, nx, ny := len(both), len(one), len(two)
	out := []byte{}
	for k := 1; k <= n; k++ {
		if k > 1 {
			out = append(out, ' ')
		}
		lo, hi := max(0, k-nx, k-ny), min(k, nb)
		if lo > hi {
			out = append(out, "-1"...)
			continue
		}
		cost := func(j int) int64 { return B[j] + X[k-j] + Y[k-j] }
		// cost(j) is convex in j: binary search the first non-negative difference.
		l, r := lo, hi
		for l < r {
			m := (l + r) / 2
			if cost(m+1)-cost(m) >= 0 {
				r = m
			} else {
				l = m + 1
			}
		}
		out = strconv.AppendInt(out, cost(l), 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
